package com.sikboard;
import android.inputmethodservice.InputMethodService; import android.view.*; import android.widget.*; import android.view.inputmethod.InputConnection;
public class SikBoardIME extends InputMethodService { public View onCreateInputView(){ LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); TextView title=new TextView(this); title.setText("SikBoard  •  SikEmoji"); title.setTextSize(18); title.setPadding(20,12,20,12); root.addView(title); LinearLayout row=new LinearLayout(this); String[] emojis={"💀","😂","😎","❤️","🔥","⭐","✨","🧩"}; for(String e:emojis){ Button b=new Button(this); b.setText(e); b.setTextSize(24); b.setOnClickListener(v->{ InputConnection ic=getCurrentInputConnection(); if(ic!=null) ic.commitText(((Button)v).getText(),1); }); row.addView(b,new LinearLayout.LayoutParams(0,70,1)); } root.addView(row); TextView info=new TextView(this); info.setText("Özel emoji / skin / renderer altyapısı için başlangıç çekirdeği"); info.setPadding(20,16,20,16); root.addView(info); return root; } }
